SELECT FROM comment c JOIN `user` u ON u.id = c.author_id LEFT JOIN `user` ru ON ru.id = c.reply_to_user_id WHERE c.video_id = #{videoId} AND c.root_id IS NULL AND c.status = 1 AND c.deleted_at IS NULL
AND c.id < #{cursorId}
ORDER BY c.id DESC LIMIT #{limit}

